<script setup lang="ts">
import { errorMessage } from '@/utils'
import { ref,computed,onBeforeUnmount,watch,nextTick } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Plus,Pencil,Star,Download,RefreshCw,Sparkles,Square } from 'lucide-vue-next'
import EventEditor from './EventEditor.vue'
import ResourceLinks from './ResourceLinks.vue'
import ProjectSummaryPanel from './ProjectSummaryPanel.vue'
import {summaryGroup} from '@/utils/project-summary'
import ProjectDialog from '@/components/project/ProjectDialog.vue'
import { workspace,localDate } from '@/utils/workspace-api'
import type { TimelineEvent,EvidenceReport,SummaryKind } from '@/types/workspace'
import type { ProjectSession } from '@/types/project'
import '@/styles/workspace.css'
const props=defineProps<{id:string}>(),route=useRoute(),router=useRouter(),events=ref<TimelineEvent[]>([]),mode=ref('session'),error=ref(''),message=ref(''),busy=ref(false),editor=ref(false),editing=ref<TimelineEvent>(),evidence=ref<EvidenceReport|null>(null),showDrafts=ref(true)
const workflowSession=ref<ProjectSession|null>(null),generating=computed(()=>workflowSession.value?.workflow?.state==='running')
const automatic=ref(false)
const undoPreview=ref<{sessionId:string;eligible:Array<{id:string;title:string}>;retained:Array<{id:string;title:string;reason:string}>}|null>(null)
const workflowDetail=computed(()=>{
  const session=workflowSession.value;if(!session)return ''
  if(session.error)return session.error
  if(session.workflow?.state==='complete')return '日志与提交依据已保存，可查看会话、编辑记录或撤销本次生成。'
  const label=session.messages.at(-1)?.events.at(-1)?.label||''
  if(label.startsWith('read_project_history'))return '正在回顾提交历史，已保存续读位置。'
  if(label.startsWith('read_project_commit'))return '正在核对提交中的具体变更。'
  if(label.startsWith('record_project_event'))return '正在保存已整理的项目日志。'
  if(label.startsWith('read_project_events'))return '正在核对已有日志，避免重复记录。'
  return session.messages.at(-1)?.text||'整理任务已创建，等待模型处理。'
})
watch(()=>props.id,async id=>{try{const value=await window.baoyi.project.automation(id);if(props.id===id)automatic.value=value.enabled}catch(e){error.value=errorMessage(e)}},{immediate:true})
async function toggleAutomatic(){await action(async()=>{automatic.value=(await window.baoyi.project.automation(props.id,!automatic.value)).enabled})}
let revision=0
const published=computed(()=>events.value.filter(e=>e.status==='published')),drafts=computed(()=>events.value.filter(e=>e.status==='draft'))
const groups=computed(()=>{const map=new Map<string,TimelineEvent[]>();for(const e of published.value){let label='';const date=new Date(e.occurredAt);if(mode.value==='day')label=localDate(date);if(mode.value==='week'){date.setDate(date.getDate()-(date.getDay()+6)%7);label=localDate(date)+' 起的一周'}if(mode.value==='version')label=e.version||'未标记版本 / 阶段';const key=mode.value==='session'?e.id:label;map.set(key,[...(map.get(key)||[]),e])}return [...map].map(([key,items])=>({key,label:mode.value==='session'?'':key,items}))})
async function load(){const run=++revision;try{const rows=await workspace.timeline.events(props.id);if(run===revision){events.value=rows}}catch(e){if(run===revision)error.value=errorMessage(e)}}
watch(()=>props.id,async id=>{events.value=[];error.value='';evidence.value=null;workflowSession.value=null;void load();try{const sessions=await window.baoyi.project.sessions(id),latest=sessions.find(s=>s.workflow);if(latest){const value=await window.baoyi.project.session(latest.id);if(props.id===id)workflowSession.value=value}}catch(e){error.value=errorMessage(e)}},{immediate:true})
const unsubscribe=workspace.onChanged(()=>void load())
const unsubscribeSession=window.baoyi.project.onSession(session=>{if(session.projectId===props.id&&session.workflow){workflowSession.value=session;if(session.workflow.state!=='running'){void load();const id=props.id;void window.baoyi.project.automation(id).then(value=>{if(props.id===id)automatic.value=value.enabled}).catch(e=>{if(props.id===id)error.value=errorMessage(e)})}}})
onBeforeUnmount(()=>{revision++;unsubscribe();unsubscribeSession()})
async function action(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';try{await fn();await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function edit(event?:TimelineEvent){editing.value=event;editor.value=true}
async function check(){await action(async()=>{evidence.value=await workspace.timeline.check(props.id);message.value=evidence.value.message})}
async function generate(ai:boolean){await action(async()=>{if(ai){workflowSession.value=await window.baoyi.project.organize(props.id);message.value='已创建整理会话，日志会自动保存。'}else{const value=await workspace.timeline.generate(props.id,false);message.value=value?'已生成事实草稿，可编辑后发布。':'没有新的记录依据。';showDrafts.value=true}evidence.value=null})}
function openSession(id:string){void router.replace({query:{...route.query,tab:'chat',session:id}})}
async function resume(){if(workflowSession.value)await action(async()=>{workflowSession.value=await window.baoyi.project.resumeOrganize(workflowSession.value!.id)})}
async function stop(){if(workflowSession.value)await action(()=>window.baoyi.project.cancelMessage(workflowSession.value!.id))}
async function undo(event:TimelineEvent){await action(async()=>{const result=await window.baoyi.project.undoEvent(props.id,event.id);message.value=result.reason})}
async function previewUndo(){const sessionId=workflowSession.value?.id;if(sessionId)await action(async()=>{undoPreview.value={sessionId,...await window.baoyi.project.undoBatch(props.id,sessionId)}})}
async function confirmUndo(){if(!undoPreview.value)return;await action(async()=>{const result=await window.baoyi.project.undoBatch(props.id,undoPreview.value!.sessionId,true);message.value=`已撤销 ${result.undone} 条生成记录，保留 ${result.retained.length} 条后续修订或关联记录。`;undoPreview.value=null})}
async function remove(event:TimelineEvent){if(!confirm('移除此项目记录？关联的原资料保留。'))return;await action(()=>workspace.timeline.remove(props.id,event.id))}
watch(()=>[route.query.event,events.value.length],async()=>{await nextTick();const id=String(route.query.event||'');if(id)document.getElementById('event-'+id)?.scrollIntoView({block:'center'})})
</script>
<template><section class="ws timeline"><header class="ws-header"><div><h2>这件事的来龙去脉</h2><p class="ws-muted">留下经过，也记住下一步。</p></div><button class="ws-button" :disabled="busy" @click="action(async()=>{const file=await workspace.timeline.export(id);if(file)message='日志已导出到 '+file})"><Download :size="15"/>导出日志</button><button class="ws-button primary" @click="edit()"><Plus :size="17"/>记一笔</button></header><p v-if="error" class="ws-error" role="alert">{{error}}</p><div class="ws-toolbar"><h3>项目日志 <span class="ws-muted">{{published.length}}</span></h3><span class="ws-spacer"/><div class="ws-tabs"><button v-for="(label,key) in {session:'工作段',day:'天',week:'周',version:'版本'}" :key="key" :class="{active:mode===key}" @click="mode=key">{{label}}</button></div></div><div class="timeline-suggestion"><button class="ws-button" :aria-pressed="automatic" @click="toggleAutomatic">自动记录：{{automatic?'开':'关'}}</button><span class="ws-muted">{{message||'让助手回顾历史，自动记录进展。'}}</span><button v-if="generating" class="ws-button" @click="stop"><Square :size="14"/>停止生成</button><template v-else><button class="ws-button" :disabled="busy" @click="check"><RefreshCw :size="14"/>检查变化</button><button class="ws-button" :disabled="busy" @click="generate(false)">事实草稿</button><button class="ws-button" :disabled="busy" @click="generate(true)"><Sparkles :size="14"/>AI 整理</button></template></div><section v-if="workflowSession" class="timeline-workflow"><div><strong>{{workflowSession.workflow?.state==='running'?'助手正在整理历史':workflowSession.workflow?.state==='complete'?'本次整理已完成':workflowSession.repository&&workflowSession.repository.status!=='ready'?'需要确认仓库':'整理已保存，可继续'}}</strong><p class="ws-muted">{{workflowDetail}}</p></div><button class="ws-button" @click="openSession(workflowSession.id)">查看会话</button><button v-if="!generating&&published.some(e=>e.generated?.sessionId===workflowSession?.id)" class="ws-button" :disabled="busy" @click="previewUndo">撤销本次生成</button><button v-if="workflowSession.workflow?.state==='paused'" class="ws-button primary" :disabled="busy" @click="workflowSession.repository && workflowSession.repository.status !== 'ready' ? openSession(workflowSession.id) : resume()">{{ workflowSession.repository && workflowSession.repository.status !== 'ready' ? '选择仓库' : '继续整理' }}</button></section><details v-if="evidence?.key" class="timeline-evidence"><summary>查看本次依据</summary><pre>{{evidence.text}}</pre></details>
<section v-if="drafts.length" class="timeline-drafts"><button class="ws-button" @click="showDrafts=!showDrafts">待确认 {{drafts.length}} 条 {{showDrafts?'收起':'展开'}}</button><template v-if="showDrafts"><article v-for="event in drafts" :id="'event-'+event.id" :key="event.id" class="timeline-event draft"><header><h3>{{event.title}}</h3><span class="ws-badge">草稿</span></header><p class="ws-pre">{{event.body}}</p><details class="timeline-evidence"><summary>来源依据 · {{event.evidence.length}} 条</summary><pre>{{event.evidence.join('\n')}}</pre></details><div class="ws-toolbar"><button class="ws-button primary" :disabled="busy" @click="action(()=>workspace.timeline.publish(id,event.id))">确认发布</button><button class="ws-button" @click="edit(event)">编辑草稿</button><button class="ws-button" :disabled="busy" @click="action(()=>workspace.timeline.dismiss(id,event.id))">忽略建议</button></div></article></template></section>
<div v-if="!published.length" class="ws-empty"><h2>从第一笔开始</h2><p>记录一次推进、一个决定，或一个值得记住的结果。代码项目与日常事项都可以从这里开始。</p><button class="ws-button primary" @click="edit()">记一笔</button></div><section v-for="group in groups" :key="group.key" class="timeline-group"><header v-if="group.label" class="timeline-group-title"><h3>{{group.label}}</h3><p class="ws-muted">{{group.items.length}} 次记录 · {{group.items.filter(e=>e.milestone).length}} 个重要节点</p></header>
<ProjectSummaryPanel v-if="mode!=='session'" :project-id="id" :kind="mode as SummaryKind" :group-key="summaryGroup(group.items[0],mode as SummaryKind)"/>
<article v-for="event in group.items" :id="'event-'+event.id" :key="event.id" class="timeline-event"><header><time>{{new Date(event.occurredAt).toLocaleDateString()}}</time><Star v-if="event.milestone" :size="15"/><span v-if="event.version" class="ws-badge">{{event.version}}</span><button v-if="event.generated" class="ws-badge" title="查看生成会话" @click="openSession(event.generated.sessionId)">AI 生成</button><span v-if="event.revised" class="ws-badge">已人工修订</span><span class="timeline-event-actions"><button v-if="event.generated&&!event.revised" class="ws-button" :disabled="busy||generating" @click="undo(event)">撤销生成</button><button class="ws-icon" aria-label="编辑项目记录" @click="edit(event)"><Pencil :size="15"/></button><button class="ws-icon" aria-label="移除项目记录" :disabled="busy" @click="remove(event)">×</button></span></header><h3>{{event.title}}</h3><p class="ws-pre">{{event.body}}</p><details v-if="event.evidence.length" class="timeline-evidence"><summary>查看 {{event.evidence.length}} 条原始依据</summary><pre>{{event.evidence.join('\n')}}</pre></details><ResourceLinks owner="event" :id="event.id" title="记录中的资料"/></article></section><ResourceLinks owner="project" :id="id" title="项目关联资料"/>
<ProjectDialog v-if="undoPreview" title="撤销本次自动生成" :busy="busy" @close="undoPreview=null"><div class="ws"><p>将撤销 {{undoPreview.eligible.length}} 条尚未修改的生成记录。会话和提交依据仍保留。</p><ul><li v-for="row in undoPreview.eligible" :key="row.id">{{row.title}}</li></ul><template v-if="undoPreview.retained.length"><h3>以下记录会保留</h3><p v-for="row in undoPreview.retained" :key="row.id">{{row.title}}：{{row.reason}}</p></template></div><template #footer><div class="ws"><button class="ws-button" @click="undoPreview=null">取消</button><button class="ws-button danger" :disabled="busy||!undoPreview.eligible.length" @click="confirmUndo">确认撤销 {{undoPreview.eligible.length}} 条</button></div></template></ProjectDialog><EventEditor v-if="editor" :project-id="id" :event="editing" @close="editor=false" @saved="load"/></section></template>
<style scoped>
.timeline-workflow{display:flex;gap:12px;align-items:center;padding:14px 16px;margin-bottom:22px;border:1px solid var(--divider);border-left:3px solid var(--accent);border-radius:6px;background:var(--ws-tint)}.timeline-workflow>div{flex:1;min-width:0}.timeline-workflow p{overflow-wrap:anywhere}.timeline-event-actions>.ws-button{padding:4px 8px;font-size:11px}
.timeline{padding:26px 28px}.timeline>.ws-header h2{margin:0}.timeline-context{display:flex;gap:24px;border:1px solid var(--divider);border-radius:6px;padding:21px}.timeline-context>section{flex:1;min-width:0}.timeline-context>section+section{border-left:1px solid var(--divider);padding-left:24px}.timeline-context h3{font-size:12px;font-weight:500;color:var(--text-sub)}.timeline-context p{font-size:14px;margin-bottom:0}.timeline-suggestion{display:flex;gap:9px;align-items:center;flex-wrap:wrap;border:1px solid var(--divider);padding:12px;border-radius:5px;margin-bottom:18px}.timeline-suggestion>span{flex:1;min-width:190px;overflow-wrap:anywhere}.timeline-suggestion .ws-button{font-size:12px;padding:6px 10px}.timeline-event{position:relative;border-left:1px solid var(--divider);margin-left:7px;padding:0 0 26px 25px}.timeline-event:before{content:'';position:absolute;width:7px;height:7px;border-radius:50%;border:1px solid var(--accent);background:var(--bg-main);left:-4px;top:9px}.timeline-event header{display:flex;align-items:center;gap:10px;margin-bottom:9px}.timeline-event header time{font-size:12px;color:var(--text-sub)}.timeline-event header svg{color:var(--accent)}.timeline-event-actions{margin-left:auto;display:flex}.timeline-event>h3{font-size:17px;font-weight:500}.timeline-event>p{font-size:14px;line-height:1.9}.timeline-event .ws-links{max-width:750px}.timeline-evidence{font-size:12px;color:var(--text-sub);margin:12px 0}.timeline-evidence summary{cursor:pointer}.timeline-evidence pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto;padding:15px;background:var(--ws-tint);font-size:11px}.timeline-group-title{padding:16px 0 18px}.timeline-group-title h3{font-size:16px}.timeline-drafts{margin:18px 0}.timeline-drafts .draft{margin:15px 0;background:var(--ws-tint);border:1px solid var(--divider);border-radius:6px;padding:20px}.timeline-drafts .draft:before{display:none}@media(max-width:900px){.timeline{padding:20px 16px}.timeline-context{gap:15px;padding:16px}.timeline-context>section+section{padding-left:15px}}
</style>
